// This script scans the ./migrations directory for .sql files,
// sorts them in lexical order (which is typically the order you want for sequential migrations),
// and logs each filename that would be applied.
// It does NOT actually execute the SQL – it only demonstrates the order of application.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

// Read the directory contents
fs.readdir(migrationsDir, (err, files) => {
  if (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }

  // Filter for .sql files only
  const sqlFiles = files.filter(f => f.endsWith('.sql'));

  // Sort files to ensure deterministic order (e.g., 001_init.sql, 002_add_user.sql)
  sqlFiles.sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations to apply (in order):');
  sqlFiles.forEach(file => {
    console.log(' -', file);
    // Here you could read and execute the SQL, e.g.:
    // const sql = fs.readFileSync(path.join(migrationsDir, file), 'utf8');
    // db.run(sql);
  });
});

