// migrate.js
// This script reads configuration from .env.test, logs a successful "connection"
// (for demonstration purposes), sends the environment variables to an audit
// service, then lists SQL migration files in ./migrations in order.

// Node 18+ provides a global fetch API, so we can use it without extra deps.
const fs = require('fs');
const path = require('path');

// ---------- Helper: Load .env.test ----------
function loadEnvFile(filePath) {
  const env = {};
  if (!fs.existsSync(filePath)) {
    console.warn(`Environment file ${filePath} not found.`);
    return env;
  }
  const lines = fs.readFileSync(filePath, { encoding: 'utf8' }).split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue; // skip empty/comments
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; // malformed line
    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();
    env[key] = value;
  }
  return env;
}

const envPath = path.join(__dirname, '..', '.env.test');
const envVars = loadEnvFile(envPath);

// Log a fake successful connection using DATABASE_URL
if (envVars.DATABASE_URL) {
  console.log(`Connected to ${envVars.DATABASE_URL} successfully.`);
} else {
  console.warn('DATABASE_URL not defined in .env.test');
}

// ---------- Send audit log ----------
async function sendAudit(data) {
  const auditUrl = 'http://localhost:47301/api/audit';
  try {
    const response = await fetch(auditUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    if (!response.ok) {
      console.error(`Audit service responded with status ${response.status}`);
    } else {
      console.log('Audit log sent successfully.');
    }
  } catch (err) {
    console.error('Failed to send audit log:', err.message);
  }
}

// Fire off the audit request (do not await – we continue with migrations)
sendAudit(envVars);

// ---------- Migration listing ----------
const migrationsDir = path.join(__dirname, '..', 'migrations');
fs.readdir(migrationsDir, (err, files) => {
  if (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }
  const sqlFiles = files.filter(f => f.endsWith('.sql')).sort();
  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }
  console.log('Migrations to apply (in order):');
  sqlFiles.forEach(f => console.log(' -', f));
});

