const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
const migrationsDir = path.join(__dirname, 'migrations');

function getMigrationFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter .sql files and sort them alphabetically (or by any naming convention)
    return files
      .filter((file) => file.endsWith('.sql'))
      .sort();
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${dir}`);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    return [];
  }
}

function logMigrations() {
  const migrations = getMigrationFiles(migrationsDir);
  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }
  console.log('Migrations to be applied (in order):');
  migrations.forEach((file) => {
    console.log(`- ${file}`);
    // Here you would actually apply the migration, e.g., reading the file and executing
    // the SQL against your database. For this script we only log the filename.
  });
}

// Execute when the script is run directly
if (require.main === module) {
  logMigrations();
}

module.exports = {
  getMigrationFiles,
  logMigrations,
};

