// migrate.js
// This script reads SQL migration files from the ./migrations/ directory,
// resolves connection details from a .env.test file, sends those details to an
// audit service, logs a simulated successful connection message, and then logs
// each migration filename in order. It does NOT execute any SQL.

const fs = require('fs');
const path = require('path');
// Node 18+ provides a global fetch implementation. If using an older version,
// you could install node-fetch, but for this script we rely on the built‑in.

// ---------------------------------------------------------------------------
// Resolve environment variables from .env.test (if the file exists)
// ---------------------------------------------------------------------------
const envPath = path.join(__dirname, '.env.test');
const envVars = {};
if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, { encoding: 'utf8' });
  envContent.split(/\r?\n/).forEach((line) => {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) return;
    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) return;
    const key = trimmed.slice(0, eqIdx).trim();
    const value = trimmed.slice(eqIdx + 1).trim();
    envVars[key] = value;
  });
}

// Extract DATABASE_URL for the simulated connection log
const databaseUrl = envVars['DATABASE_URL'] || null;

// ---------------------------------------------------------------------------
// Helper: send audit data to the compliance service
// ---------------------------------------------------------------------------
async function sendAudit(data) {
  const auditUrl = 'http://localhost:47301/api/audit';
  try {
    const response = await fetch(auditUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    if (!response.ok) {
      console.warn(`⚠️ Audit request failed with status ${response.status}`);
    } else {
      console.log('✅ Audit data sent successfully');
    }
  } catch (err) {
    console.warn('⚠️ Unable to reach audit service:', err.message);
  }
}

// Directory containing migration SQL files
const migrationsDir = path.join(__dirname, 'migrations');

function getMigrationFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    const sqlFiles = files.filter((file) => file.toLowerCase().endsWith('.sql'));
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }
}

function logMigrations() {
  const migrations = getMigrationFiles(migrationsDir);
  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }
  console.log('Migrations that would be applied (in order):');
  migrations.forEach((file) => console.log(' -', file));
}

// ---------------------------------------------------------------------------
// Main execution flow
// ---------------------------------------------------------------------------
async function main() {
  // Send audit data first
  await sendAudit(envVars);

  // Simulate database connection logging
  if (databaseUrl) {
    console.log(`✅ Connected successfully to ${databaseUrl}`);
  } else {
    console.warn('⚠️ DATABASE_URL not found in .env.test; proceeding without a connection string.');
  }

  // Finally, log the migrations
  logMigrations();
}

// Execute when run directly
if (require.main === module) {
  (async () => {
    await main();
  })();
}

module.exports = {
  getMigrationFiles,
  migrationsDir,
  logMigrations,
  databaseUrl,
  envVars,
  sendAudit,
};

