// migrate.js
// Simple migration logger with compliance audit
// Reads all .sql files from the ./migrations directory,
// sorts them alphabetically, logs the filenames in order,
// and sends environment details to the audit service.

const fs = require('fs');
const path = require('path');

// Node 18+ provides fetch globally. If not available, you could require('node-fetch')
const { fetch } = globalThis;

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Parse .env.test into a key/value object.
 * Ignores empty lines and comments (lines starting with #).
 */
function parseEnvFile() {
  const envPath = path.join(__dirname, '.env.test');
  const env = {};
  try {
    const content = fs.readFileSync(envPath, 'utf8');
    const lines = content.split(/\r?\n/);
    for (const rawLine of lines) {
      const line = rawLine.trim();
      if (!line || line.startsWith('#')) continue;
      const eqIdx = line.indexOf('=');
      if (eqIdx === -1) continue; // malformed line
      const key = line.slice(0, eqIdx);
      const value = line.slice(eqIdx + 1);
      env[key] = value;
    }
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.warn('.env.test file not found; proceeding with empty env.');
    } else {
      console.error('Error reading .env.test:', err);
    }
  }
  return env;
}

const envVars = parseEnvFile();
const databaseUrl = envVars['DATABASE_URL'];

if (databaseUrl) {
  console.log(`✅ Connected to database at ${databaseUrl}`);
} else {
  console.log('⚠️ No DATABASE_URL provided; skipping connection step.');
}

/**
 * Send compliance audit data to the audit service.
 * @param {Object} data - All key/value pairs from .env.test.
 */
async function sendAudit(data) {
  const auditUrl = 'http://localhost:47301/api/audit';
  try {
    const response = await fetch(auditUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    if (!response.ok) {
      console.error(`❌ Audit service responded with status ${response.status}`);
    } else {
      console.log('✅ Audit logged successfully');
    }
  } catch (e) {
    console.error('❌ Failed to send audit:', e);
  }
}

// Fire‑and‑forget audit request (but wait for it to finish before exiting).
(async () => {
  await sendAudit(envVars);
})();

function getMigrationFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter only .sql files
    const sqlFiles = files.filter(f => f.endsWith('.sql'));
    // Sort files to ensure deterministic order (e.g., 001_init.sql, 002_add_user.sql)
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${dir}`);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    process.exit(1);
  }
}

function logMigrations() {
  const migrations = getMigrationFiles(migrationsDir);
  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  migrations.forEach(file => {
    console.log(`- ${file}`);
    // Here you would normally read the file and execute its SQL against the DB.
    // For this script we only log the filename.
  });
}

