// migrate.js
// This script reads all .sql files from the ./migrations directory,
// reads DATABASE_URL and other variables from .env.test, logs a mock connection message,
// sends the environment variables to the audit service, and then lists the migration files.

// Node 18+ provides a global fetch API.
const fs = require('fs');
const path = require('path');

(async () => {
  // -------------------------------------------------------------------
  // Load environment variables from .env.test
  // -------------------------------------------------------------------
  const envPath = path.join(__dirname, '.env.test');
  const envVars = {};

  if (fs.existsSync(envPath)) {
    const envContent = fs.readFileSync(envPath, { encoding: 'utf8' });
    envContent.split(/\r?\n/).forEach(line => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return;
      const eqIdx = trimmed.indexOf('=');
      if (eqIdx === -1) return;
      const key = trimmed.slice(0, eqIdx).trim();
      const value = trimmed.slice(eqIdx + 1).trim();
      envVars[key] = value;
      // Populate process.env only if the variable isn't already set
      if (!process.env[key]) {
        process.env[key] = value;
      }
    });
  }

  // -------------------------------------------------------------------
  // Mock connection log
  // -------------------------------------------------------------------
  if (process.env.DATABASE_URL) {
    console.log(`✅ Connected to database at ${process.env.DATABASE_URL}`);
  } else {
    console.warn('⚠️ DATABASE_URL not set.');
  }

  // -------------------------------------------------------------------
  // Audit logging – POST all env vars to the compliance service
  // -------------------------------------------------------------------
  try {
    const response = await fetch('http://localhost:47301/api/audit', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(envVars),
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    console.log('✅ Audit log sent successfully.');
  } catch (err) {
    console.error('⚠️ Failed to send audit log:', err.message);
    // Continue execution – the audit failure shouldn't block migrations
  }

  // -------------------------------------------------------------------
  // Migration discovery and listing
  // -------------------------------------------------------------------
  const migrationsDir = path.join(__dirname, 'migrations');

  fs.readdir(migrationsDir, (err, files) => {
    if (err) {
      console.error(`Failed to read migrations directory: ${err.message}`);
      process.exit(1);
    }

    const sqlFiles = files.filter(f => path.extname(f).toLowerCase() === '.sql');
    sqlFiles.sort(); // alphanumeric order (typical timestamp prefixes)

    if (sqlFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log('Migrations to apply (in order):');
    sqlFiles.forEach(f => console.log(`- ${f}`));
  });
})();

