// migrate.js
// Simple migration script that scans the ./migrations directory for .sql files,
// sorts them in alphabetical order (or any desired order), and logs each filename
// that would be applied. This script does NOT execute the SQL files; it only
// demonstrates the ordering and logging logic.

const fs = require('fs').promises;
const path = require('path');

async function getMigrationFiles(dir) {
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    // Filter only .sql files (ignore directories, other extensions)
    const sqlFiles = entries
      .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
      .map(entry => entry.name);

    // Sort the files to ensure deterministic order. Many projects use a
    // prefix like 001_initial.sql, 002_add_user.sql, etc. Alphabetical sort works
    // for that convention.
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory "${dir}" does not exist.`);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    process.exit(1);
  }
}

async function main() {
  const migrationsDir = path.resolve(__dirname, 'migrations');
  const files = await getMigrationFiles(migrationsDir);

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  for (const file of files) {
    console.log(`- ${file}`);
    // Here you would normally read the file and execute its SQL against the DB.
    // e.g., const sql = await fs.readFile(path.join(migrationsDir, file), 'utf8');
    // await db.query(sql);
  }
}

main();

