      const value = trimmed.slice(eqIdx + 1).trim();
      env[key] = value;
      // Populate process.env for convenience
      process.env[key] = value;
    }
    return env;
  } catch (err) {
    console.error('Failed to load .env.test:', err);
    process.exit(1);
  }
}

