// audit service, and logs a fake successful connection.

const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
const migrationsDir = path.resolve(__dirname, 'migrations');

function getMigrationFiles(dir) {
  // Read all entries in the directory
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (err) {
    console.error(`Failed to read migrations directory: ${err.message}`);
    process.exit(1);
  }

  // Filter for files with .sql extension
  const sqlFiles = entries
    .filter((entry) => entry.isFile() && entry.name.endsWith('.sql'))
    .map((entry) => entry.name);

  // Sort files to ensure deterministic order (e.g., 001_init.sql, 002_add.sql)
  sqlFiles.sort();
  return sqlFiles;
}

function logMigrations() {
  const files = getMigrationFiles(migrationsDir);
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  files.forEach((file) => {
    console.log(`- ${file}`);
  });
}

// Load environment variables from .env.test
function loadEnv(filePath) {
  const env = {};
  try {
    const data = fs.readFileSync(filePath, { encoding: 'utf8' });
    data.split(/\n/).forEach((line) => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return;
      const eqIdx = trimmed.indexOf('=');
      if (eqIdx === -1) return;
      const key = trimmed.slice(0, eqIdx).trim();
      const value = trimmed.slice(eqIdx + 1).trim();
      // Strip surrounding quotes if present
      env[key] = value.replace(/^"|"$/g, '').replace(/^'|'$/g, '');
    });
  } catch (err) {
    console.warn(`Could not load .env.test: ${err.message}`);
  }
  return env;
}

