#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

// ---------------------------
// Load environment variables from .env.test
// ---------------------------
const envPath = path.join(__dirname, '.env.test');
let envVars = {};
try {
  const envContent = fs.readFileSync(envPath, { encoding: 'utf8' });
  const lines = envContent.split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;
    const key = trimmed.slice(0, idx).trim();
    const value = trimmed.slice(idx + 1).trim();
    envVars[key] = value;
  }
} catch (e) {
  // .env.test may not exist; continue with empty envVars
}

// Log connection simulation if DATABASE_URL is present
if (envVars.DATABASE_URL) {
  console.log(`Connected to database at ${envVars.DATABASE_URL}`);
} else {
  console.log('DATABASE_URL not set in .env.test – skipping connection log.');
}

// ---------------------------
// Audit logging – send env vars to compliance service
// ---------------------------
function postAudit(data) {
  const payload = JSON.stringify(data);
  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
    },
  };

  const req = http.request(options, (res) => {
    let responseBody = '';
    res.on('data', (chunk) => (responseBody += chunk));
    res.on('end', () => {
      console.log(`Audit service responded with status ${res.statusCode}`);
      if (responseBody) console.log(`Response body: ${responseBody}`);
    });
  });

  req.on('error', (err) => {
    console.error('Failed to send audit request:', err.message);
  });

  req.write(payload);
  req.end();
}

// Send audit data (all env vars)
postAudit(envVars);

// ---------------------------
// Migration handling
// ---------------------------
const migrationsDir = path.join(__dirname, 'migrations');

fs.readdir(migrationsDir, (err, files) => {
  if (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${migrationsDir}`);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    process.exit(1);
  }

  const sqlFiles = files.filter((f) => f.endsWith('.sql')).sort(); // alphabetical order

  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  sqlFiles.forEach((file) => {
    console.log(`Would apply migration: ${file}`);
    // Real implementation would execute the SQL against the DB.
  });
});

