// migrate.js
// This script scans the ./migrations/ directory for .sql files,
// sorts them in lexical order, and logs each filename that would be applied.
// It does NOT execute the SQL; it only demonstrates the order of migrations.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    // Filter only files with .sql extension (case-insensitive)
    const sqlFiles = entries
      .filter(entry => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
      .map(entry => entry.name);
    // Sort files to ensure deterministic order (e.g., timestamp prefixes)
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${dir}`);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    process.exit(1);
  }
}

function main() {
  const files = getSqlFiles(migrationsDir);
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  files.forEach(file => {
    console.log(`- ${file}`);
  });
}

if (require.main === module) {
  main();
}

