// migrate.js
// This script reads SQL files from the ./migrations/ directory
// and logs each filename it would apply, in order (alphabetical).
// It also reads DATABASE_URL from a .env.test file and logs a faux
// successful connection message.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envFilePath = path.join(__dirname, '.env.test');

/**
 * Simple .env parser – extracts key=value pairs, ignoring comments and empty lines.
 */
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const result = {};
    content.split(/\r?\n/).forEach(line => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return;
      const eqIdx = trimmed.indexOf('=');
      if (eqIdx === -1) return;
      const key = trimmed.slice(0, eqIdx).trim();
      let value = trimmed.slice(eqIdx + 1).trim();
      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith('\'') && value.endsWith('\''))) {
        value = value.slice(1, -1);
      }
      result[key] = value;
    });
    return result;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.warn(`Env file not found at ${filePath}. Skipping database URL loading.`);
      return {};
    }
    throw err;
  }
}

function getDatabaseUrl() {
  const env = parseEnvFile(envFilePath);
  return env['DATABASE_URL'] || null;
}

function getSqlFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter for .sql files only
    return files.filter(f => f.endsWith('.sql')).sort();
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${dir}`);
      process.exit(1);
    }
    throw err;
  }
}

function logMigrations() {
  const sqlFiles = getSqlFiles(migrationsDir);
  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }
  console.log('Migrations to apply (in order):');
  sqlFiles.forEach(file => {
    console.log('- ' + file);
  });
}

// Main execution flow
logMigrations();

const dbUrl = getDatabaseUrl();
if (dbUrl) {
  console.log(`✅ Connected to database at ${dbUrl}`);
} else {
  console.log('⚠️ DATABASE_URL not set – skipping connection log.');
}

