// migrate.js
// This script reads SQL files from the ./migrations/ directory
// and logs each filename it would apply, in order (alphabetical).
// It also reads all variables from a .env.test file and:
//   • Posts them as JSON to the migration audit service at http://localhost:47301/api/audit
//   • Logs a faux successful database connection using DATABASE_URL.

const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');
const envFilePath = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

/** Simple .env parser – extracts key=value pairs, ignoring comments and empty lines. */
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const result = {};
    content.split(/\r?\n/).forEach(line => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return;
      const eqIdx = trimmed.indexOf('=');
      if (eqIdx === -1) return;
      const key = trimmed.slice(0, eqIdx).trim();
      let value = trimmed.slice(eqIdx + 1).trim();
      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith('\'') && value.endsWith('\''))) {
        value = value.slice(1, -1);
      }
      result[key] = value;
    });
    return result;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.warn(`Env file not found at ${filePath}.`);
      return {};
    }
    throw err;
  }
}

/** Send audit data to the compliance service. Returns a Promise. */
function sendAudit(data) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(data);
    const url = new URL(auditUrl);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
    };
    const req = http.request(options, res => {
      let responseBody = '';
      res.on('data', chunk => (responseBody += chunk));
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✅ Audit log sent successfully.');
          resolve();
        } else {
          console.warn(`⚠️ Audit service responded with status ${res.statusCode}: ${responseBody}`);
          resolve(); // Continue even on non‑2xx
        }
      });
    });
    req.on('error', err => {
      console.error('❌ Failed to send audit log:', err.message);
      resolve(); // Continue execution despite the error
    });
    req.write(payload);
    req.end();
  });
}

function getSqlFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    return files.filter(f => f.endsWith('.sql')).sort();
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${dir}`);
      process.exit(1);
    }
    throw err;
  }
}

function logMigrations() {
  const sqlFiles = getSqlFiles(migrationsDir);
  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }
  console.log('Migrations to apply (in order):');
  sqlFiles.forEach(file => console.log('- ' + file));
}

// Main async flow
(async () => {
  const envData = parseEnvFile(envFilePath);
  // Send audit data before proceeding with migrations
  await sendAudit(envData);

  logMigrations();

  const dbUrl = envData['DATABASE_URL'];
  if (dbUrl) {
    console.log(`✅ Connected to database at ${dbUrl}`);
  } else {
    console.log('⚠️ DATABASE_URL not set – skipping connection log.');
  }
})();

// migrate.js
// This script scans the ./migrations directory for SQL files,
// sorts them (lexicographically) to determine the order of application,
// and logs each filename that would be applied.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter .sql files only
    return files.filter(f => f.endsWith('.sql'));
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }
}

function main() {
  if (!fs.existsSync(migrationsDir)) {
    console.error('Migrations directory does not exist:', migrationsDir);
    process.exit(1);
  }

  const sqlFiles = getSqlFiles(migrationsDir);
  // Sort files to apply in order (e.g., 001-init.sql, 002-add.sql)
  sqlFiles.sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  sqlFiles.forEach(file => {
    console.log(`- ${file}`);
  });
}

main();

